{
  "center": {
    "title": "The Transformer",
    "gist": "A sequence transduction model based entirely on attention mechanisms, discarding recurrence and convolutions.",
    "anchors": [
      "para:1:4",
      "sec:3",
      "para:7:1"
    ]
  },
  "concepts": [
    {
      "key": "self-attention",
      "title": "Self-Attention",
      "gist": "An attention mechanism that relates different positions within a single sequence to build an internal representation.",
      "anchors": [
        "para:2:2",
        "para:2:4",
        "sec:4"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "scaled-dot-product-attention",
      "title": "Scaled Dot-Product Attention",
      "gist": "Computes queries and keys dot products, scales by the square root of key dimension, and applies softmax over values.",
      "anchors": [
        "sec:3.2.1",
        "eq:1",
        "fig:2"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "multi-head-attention",
      "title": "Multi-Head Attention",
      "gist": "Runs multiple attention layers in parallel over different projected representation subspaces and concatenates their outputs.",
      "anchors": [
        "sec:3.2.2",
        "eq:3.2.2:u1",
        "fig:2"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "positional-encoding",
      "title": "Positional Encoding",
      "gist": "Injects order information using fixed sinusoidal or learned vectors added directly to token embeddings.",
      "anchors": [
        "sec:3.5",
        "eq:3.5:u1"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "encoder-decoder-attention",
      "title": "Encoder-Decoder Attention",
      "gist": "Allows decoder positions to attend over all positions in the input sequence using encoder outputs as keys and values.",
      "anchors": [
        "sec:3.1.decoder",
        "sec:3.2.3"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "decoder-masking",
      "title": "Masked Attention",
      "gist": "Masks subsequent positions in decoder self-attention to preserve auto-regressive generation by preventing leftward information flow.",
      "anchors": [
        "para:3.1.decoder:1",
        "para:3.2.3:1"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "position-wise-ffn",
      "title": "Position-Wise Feed-Forward Network",
      "gist": "Applies two linear transformations with a ReLU activation separately and identically to each sequence position.",
      "anchors": [
        "sec:3.3",
        "eq:2"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "residual-layer-norm",
      "title": "Residual Connections and Layer Normalization",
      "gist": "Wraps each sub-layer with a residual connection followed by layer normalization to stabilize training.",
      "anchors": [
        "para:3.1.encoder:1",
        "para:3.1.decoder:1"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "constant-path-length",
      "title": "Constant Maximum Path Length",
      "gist": "Connecting any two sequence positions in O(1) sequential operations, making long-range dependencies easier to learn.",
      "anchors": [
        "para:2:1",
        "para:4:3",
        "para:4:4",
        "tab:1"
      ],
      "grounding_guess": "concept_only",
      "is_first_principle": false
    },
    {
      "key": "learning-rate-warmup",
      "title": "Learning Rate Schedule with Warmup",
      "gist": "Increases learning rate linearly during warmup steps and then decays it proportionally to the inverse square root of step.",
      "anchors": [
        "sec:5.3",
        "eq:3"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "label-smoothing",
      "title": "Label Smoothing",
      "gist": "Regularization technique that encourages model uncertainty during training, improving accuracy and BLEU score.",
      "anchors": [
        "sec:5.4.label-smoothing"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    },
    {
      "key": "bleu-evaluation",
      "title": "BLEU Score",
      "gist": "Standard metric used to measure translation quality against reference translations.",
      "anchors": [
        "sec:6.1",
        "tab:2"
      ],
      "grounding_guess": "in_library",
      "is_first_principle": false
    },
    {
      "key": "beam-search",
      "title": "Beam Search with Length Penalty",
      "gist": "Autoregressive decoding strategy retaining top candidates at each step adjusted by a length penalty factor.",
      "anchors": [
        "para:6.1:3"
      ],
      "grounding_guess": "in_code",
      "is_first_principle": false
    }
  ],
